CREATE PROCEDURE InsertarPersona
 @FirstName NVARCHAR(50),
 @LastName NVARCHAR(50),
 @Discriminator NVARCHAR(50) -- 'Instructor' o 'Student'
AS
BEGIN
 SET NOCOUNT ON;
 IF @Discriminator = 'Instructor'
 BEGIN
 INSERT INTO Person (FirstName, LastName, Discriminator, HireDate)
 VALUES (@FirstName, @LastName, @Discriminator, GETDATE());
 END
 ELSE IF @Discriminator = 'Student'
 BEGIN
 INSERT INTO Person (FirstName, LastName, Discriminator, EnrollmentDate)
 VALUES (@FirstName, @LastName, @Discriminator, GETDATE());
 END
 ELSE
 BEGIN
 RAISERROR('El tipo de persona debe ser Instructor o Student', 16, 1);
 END
END;
GO
-- Para probar:
EXEC InsertarPersona 'Gerson', 'Hernadez', 'Student';

