-- DISPARADOR
CREATE TRIGGER verificacion
ON cliente
INSTEAD OF INSERT
AS
BEGIN
 IF EXISTS (
 SELECT 1
 FROM cliente c
 JOIN inserted i ON c.dni = i.dni
 )
 BEGIN
 PRINT 'El cliente ya existía previamente';
 END
 ELSE
 BEGIN
 INSERT INTO cliente (dni, nombre, edad)
 SELECT dni, nombre, edad
 FROM inserted;
 PRINT 'Ingresado correctamente';
 END
END;
GO

-- PROCEDIMIENTO
CREATE PROCEDURE InsertarCliente
 @dni VARCHAR(20),
 @nombre VARCHAR(100),
 @edad INT
AS
BEGIN
 SET NOCOUNT ON;
 INSERT INTO cliente (dni, nombre, edad)
 VALUES (@dni, @nombre, @edad);
END;
GO

